package com.investary.document.storage;

import java.io.InputStream;

import org.springframework.core.io.Resource;

/** Port for original PDF files. Keys are generated by the storage and never leave the backend. */
public interface DocumentStorage {

    /**
     * @return the storage key of the new file
     */
    String store(InputStream content);

    Resource load(String storageKey);

    /**
     * @return false when the file was already missing
     */
    boolean delete(String storageKey);
}
